import uuid
from datetime import datetime

from sqlalchemy import CheckConstraint, DateTime, ForeignKey, Index, UniqueConstraint, func, text
from sqlalchemy.dialects.postgresql import JSONB
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column


class Base(DeclarativeBase):
    pass


class User(Base):
    """A global account. Which studios it belongs to is decided by memberships (step 8)."""

    __tablename__ = "users"

    # Generated by Postgres, so any writer (app, seed script, raw SQL) gets an id.
    id: Mapped[uuid.UUID] = mapped_column(primary_key=True, server_default=func.gen_random_uuid())
    # ponytail: case-sensitive unique; login lowercases the email it looks up, so any signup/invite code must store it lowercased too.
    email: Mapped[str] = mapped_column(unique=True)
    name: Mapped[str]
    locale: Mapped[str] = mapped_column(server_default="en")
    # Argon2 hash, never the password. NULL = no password login (e.g. Google sign-in, step 53).
    password_hash: Mapped[str | None]


class Tenant(Base):
    """One studio. Every tenant-owned table later carries a tenant_id pointing here."""

    __tablename__ = "tenants"

    id: Mapped[uuid.UUID] = mapped_column(primary_key=True, server_default=func.gen_random_uuid())
    name: Mapped[str]
    # ponytail: any string accepted; check format (lowercase, URL-safe) at the API boundary.
    slug: Mapped[str] = mapped_column(unique=True)
    # IANA name such as "Asia/Jerusalem", never an offset (offsets change with DST).
    # ponytail: not validated here; check with zoneinfo when sessions are created (step 18).
    timezone: Mapped[str]
    default_locale: Mapped[str] = mapped_column(server_default="en")
    # The optional modules this studio has switched on, e.g. ["booking"]. Set by the seed script for
    # now. Names are checked against KNOWN_MODULES (app/deps.py) where they are used, not here.
    modules: Mapped[list[str]] = mapped_column(JSONB, server_default=text("'[]'::jsonb"))


class Membership(Base):
    """Links a user to a studio with a role, so one account can belong to several studios."""

    __tablename__ = "memberships"
    __table_args__ = (
        UniqueConstraint("tenant_id", "user_id"),
        # CHECK rather than a Postgres ENUM: adding a role (head_coach, step 48) is a plain
        # drop + add of this constraint.
        CheckConstraint("role IN ('owner', 'coach', 'member')", name="ck_memberships_role"),
    )

    id: Mapped[uuid.UUID] = mapped_column(primary_key=True, server_default=func.gen_random_uuid())
    tenant_id: Mapped[uuid.UUID] = mapped_column(ForeignKey("tenants.id"))
    user_id: Mapped[uuid.UUID] = mapped_column(ForeignKey("users.id"))
    role: Mapped[str]


class ClassType(Base):
    """A kind of class a studio offers (BJJ, Pilates...). The first tenant-owned table: every row
    belongs to one studio, and every query on it must filter by that studio."""

    __tablename__ = "class_types"

    id: Mapped[uuid.UUID] = mapped_column(primary_key=True, server_default=func.gen_random_uuid())
    # Indexed: every read of this table is "the rows of this studio".
    tenant_id: Mapped[uuid.UUID] = mapped_column(ForeignKey("tenants.id"), index=True)
    # ponytail: names are not unique within a studio, so "Pilates" can be created twice. Add
    # UniqueConstraint("tenant_id", "name") plus a 409 if that ever bites.
    name: Mapped[str]
    # NULL = active. Set when an owner archives the type; never deleted, because sessions, reports
    # and notes reference it. Archived types are hidden by default and cannot get new sessions.
    archived_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    # "rsvp" (a plan, step 20) or "booking" (capacity and waitlist, steps 24-25). "booking" can only be
    # set in a studio that has the booking module on (app/class_types.py); for now it is stored only.
    attendance_mode: Mapped[str] = mapped_column(server_default="rsvp")
    __table_args__ = (
        CheckConstraint(
            "attendance_mode IN ('rsvp', 'booking')", name="ck_class_types_attendance_mode"
        ),
    )


class Participant(Base):
    """A person as one studio knows them: the thing attendance, reports and notes attach to. A user
    is global (one account), a participant belongs to one studio, so someone in two studios has
    two participants. Created together with the membership (seed, migration backfill; step 50's
    invite code must do the same)."""

    __tablename__ = "participants"
    # Also serves "the participants of this studio" (tenant_id is the leading column), so no
    # separate tenant_id index. Postgres treats NULLs as distinct, so kids without an account
    # (user_id NULL, step 47) are not limited to one per studio.
    __table_args__ = (UniqueConstraint("tenant_id", "user_id"),)

    id: Mapped[uuid.UUID] = mapped_column(primary_key=True, server_default=func.gen_random_uuid())
    tenant_id: Mapped[uuid.UUID] = mapped_column(ForeignKey("tenants.id"))
    user_id: Mapped[uuid.UUID | None] = mapped_column(ForeignKey("users.id"))
    # ponytail: copied from users.name when created and not kept in sync; a studio can later
    # rename its own participant (e.g. a nickname) without touching the global account.
    name: Mapped[str]


class ClassSession(Base):
    """One occurrence of a class type: that class, at a given time, taught by a given coach."""

    __tablename__ = "class_sessions"

    id: Mapped[uuid.UUID] = mapped_column(primary_key=True, server_default=func.gen_random_uuid())
    # Not indexed on its own: the (tenant_id, starts_at) index below also serves "this studio's sessions".
    tenant_id: Mapped[uuid.UUID] = mapped_column(ForeignKey("tenants.id"))
    class_type_id: Mapped[uuid.UUID] = mapped_column(ForeignKey("class_types.id"))
    # A user, not a membership: the API checks they are staff of this studio when it writes this.
    # ponytail: removing the coach's membership later leaves their past sessions pointing at them.
    coach_id: Mapped[uuid.UUID] = mapped_column(ForeignKey("users.id"))
    # UTC instants (timestamptz); the studio's timezone is only for display.
    starts_at: Mapped[datetime] = mapped_column(DateTime(timezone=True))
    ends_at: Mapped[datetime] = mapped_column(DateTime(timezone=True))
    # "scheduled" or "cancelled". A cancelled session stays: reports, notes and the schedule keep
    # pointing at it. There is no way back to "scheduled".
    status: Mapped[str] = mapped_column(server_default="scheduled")
    # What the class is about, written by the coach ahead of time.
    preview: Mapped[str | None]
    # Seats for booking-mode classes (step 24); NULL = unlimited. Ignored in rsvp mode.
    capacity: Mapped[int | None]
    __table_args__ = (
        CheckConstraint("status IN ('scheduled', 'cancelled')", name="ck_class_sessions_status"),
        CheckConstraint("capacity >= 1", name="ck_class_sessions_capacity_positive"),
        # Backstop for the API's check: no code path can store a session that ends before it starts.
        CheckConstraint("ends_at > starts_at", name="ck_class_sessions_ends_after_start"),
        # For the schedule query: one studio's sessions in a time window, already in order.
        Index("ix_class_sessions_tenant_id_starts_at", "tenant_id", "starts_at"),
    )


class Rsvp(Base):
    """A participant's plan for a session: going, not going or maybe. Only an intention before the
    class; whether they actually came is recorded separately (step 21). One row per participant and
    session, enforced by the composite primary key.
    ponytail: the session and the participant are not checked to be in the same studio here; the
    endpoint derives both from the caller's studio."""

    __tablename__ = "rsvps"
    __table_args__ = (
        CheckConstraint(
            "status IN ('going', 'not_going', 'maybe', 'waitlist')", name="ck_rsvps_status"
        ),
        # A queue position exists exactly while someone is waiting.
        CheckConstraint(
            "(status IS NOT DISTINCT FROM 'waitlist') = (waitlisted_at IS NOT NULL)",
            name="ck_rsvps_waitlisted_at",
        ),
    )

    session_id: Mapped[uuid.UUID] = mapped_column(ForeignKey("class_sessions.id"), primary_key=True)
    participant_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("participants.id"), primary_key=True
    )
    # The plan. NULL = no plan given (someone can attend without having RSVPed). "waitlist" is set by
    # the server, never by the client: the session was full when they asked for "going".
    status: Mapped[str | None]
    # When they joined the waitlist (the queue order); NULL for everyone not waiting.
    waitlisted_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    # What happened, kept apart from the plan so "said going, did not come" stays visible.
    # NULL = not recorded yet.
    attended: Mapped[bool | None]
    confirmed_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))


class RefreshToken(Base):
    """A long-lived login credential. Only its SHA-256 hash is stored, never the token itself."""

    __tablename__ = "refresh_tokens"

    id: Mapped[uuid.UUID] = mapped_column(primary_key=True, server_default=func.gen_random_uuid())
    user_id: Mapped[uuid.UUID] = mapped_column(ForeignKey("users.id"))
    # One family = one device's login: login starts a new family, rotation copies it to the
    # replacement. Logout revokes by family, so it also catches tokens created while it ran.
    family_id: Mapped[uuid.UUID] = mapped_column(index=True)
    # Unique: lookups go by this value, and the unique index makes them fast.
    token_hash: Mapped[str] = mapped_column(unique=True)
    # timezone=True: store a real UTC instant, not a naive wall-clock time.
    expires_at: Mapped[datetime] = mapped_column(DateTime(timezone=True))
    # NULL = still usable. Set when the token is used up (rotation) or its login is ended
    # (logout); never cleared again.
    revoked_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
